def bootstrap_statistic(data, num_samples, statistic, random_seed=None):
    bootstrapped_statistics = []
    for _ in range(num_samples):
        bootstrapped_sample = bootstrap_sample(data, random_seed)
        bootstrapped_statistic = statistic(bootstrapped_sample)
        bootstrapped_statistics.append(bootstrapped_statistic)
    return bootstrapped_statistics

