def is_valid_ipv4_address(address: str) -> bool:
    """
    Checks if the given `address` is a valid IPv4 address.
    """
    substrings = address.split(".")
    if len(substrings) != 4:
        return False
    for substring in substrings:
        if re.match(r"^\d+$", substring):
            if not 0 <= int(substring) <= 255:
                return False
        elif re.match(r"^0x[0-9a-fA-F]+$", substring):
